"""Reproduce the concise report from published, integrity-checked experiment evidence."""
import json,pathlib,gzip,base64,hashlib,collections
root=pathlib.Path('public');index=json.loads((root/'research/mission2-results.json').read_text())
def read(url):
 e=json.loads((root/url.lstrip('/')).read_text());raw=gzip.decompress(base64.b64decode(e['data']));assert hashlib.sha256(raw).hexdigest()==e['sha256'];return json.loads(raw)
def fmt(n):return 'undefined (no losses)' if n is None else f'{n:.3f}'
lines=['# Mission 2 actual research results','', 'Research remains in progress. No candidate is production-qualified or approved for demo automation by these screens. Passing engineering tests does not establish profitability.','', '## Comparable account results','', '$1,000 initial capital, 0.5% gross stop-distance risk, Binance hypothetical contract/cost profile. Costs are included in P&L but are not included in the initial stop-risk sizing budget. Each row is its own portfolio; overlapping rows must not be pooled as independent evidence.','', '| Experiment | Venue | Period | Signals | Entries | Closed | PF | Equity return % | Conservative DD % |','|---|---|---|---:|---:|---:|---:|---:|---:|']
studies=[]
for d in index['studies']:
 s=read(d['dataUrl']);studies.append(s);a=next((a for a in s['accounts'] if a['provider']=='BINANCE' and a['capital']==1000 and a['riskPct']==.5),None)
 if a:
  m=a['metrics'];lines.append(f"| {s['id']} | {s['venue']} | {s['period']['start'][:10]}–{s['period']['end'][:10]} | {sum(r['confirmed'] for r in s['funnel']['rows'])} | {m['authorizedEntries']} | {m['closedTrades']} | {fmt(m['profitFactor'])} | {fmt(m['netReturnPct'])} | {fmt(m['maximumDrawdownPct'])} |")
base=next(s for s in studies if s['id']=='ten-asset-week-baseline')
lines+=['','## January scanner funnel','','Counts are unique strategy/symbol/timeframe/closed-candle evaluations, not minute polling. Filter reasons may overlap.','', '| Raw candidates | Immediate | Conditional | Admitted | Confirmed | Watches triggered | Expired | Invalidated |','|---:|---:|---:|---:|---:|---:|---:|---:|']
keys=['rawOpportunities','immediate','conditional','admitted','confirmed','triggeredWatches','expired','invalidated'];lines.append('| '+' | '.join(str(sum(r[k] for r in base['funnel']['rows'])) for k in keys)+' |')
reasons=collections.Counter()
for r in base['funnel']['rows']:reasons.update(r['rejections'])
lines+=['','Largest diagnostic counts (overlapping; include no-opportunity observations):','']+[f'- {key}: {value}' for key,value in reasons.most_common(15)]
lines+=['','## Personal capital/risk matrix','','Same January signals, real account Brain and separate equity/margin paths. These scenarios are not independent market samples.','', '| Capital $ | Risk % | Entries | PF | Return % | DD % |','|---:|---:|---:|---:|---:|---:|']
for a in base['accounts']:
 m=a['metrics'];lines.append(f"| {a['capital']} | {a['riskPct']} | {m['authorizedEntries']} | {fmt(m['profitFactor'])} | {fmt(m['netReturnPct'])} | {fmt(m['maximumDrawdownPct'])} |")
lines+=['','## Interpretation and limits','','- The research-only removal of signal admission budgets increases confirmations, while the January portfolio remains negative after account risk checks. This does not justify removing production risk controls.','- Immediate-only avoids watches consuming signal budgets. Conditional-only has very few executed trades; an undefined PF when no loss was observed is not proof of a robust edge.','- The MicroScalper TP2 experiment improves the January/February screen slightly but does not establish a robust positive portfolio in March or the reserved October window. See the frozen experiment and its metadata correction.','- Spot is long-only. USD-M uses its own native derivatives archives; it is not a renamed spot replay. Funding is a documented conservative reserve, not genuine historical funding.','- Actual inventory is 30 definitions (10 primary, 20 specialist/support), correcting the earlier 29-definition inventory description. Forex/Gold definitions are visible but have no genuine broker-grade campaign results here.','- Seventy native monthly archives were checked byte-for-byte against acquisition checksums, and decoded rows were checked against their ZIP contents. The selected ten-symbol universe is not survivorship-neutral.','- Contract/fee/spread/slippage assumptions need historical venue verification. Bybit account/provider parity is engineering-tested, but these Binance venue results do not certify historical Bybit fills.','- Public broker archive requests returned HTTP 429. MT5 broker historical bid/ask, instrument specifications and rapid Gold tick data are unavailable. No Forex/Gold profitability, empirical prop pass/payout rate, or funded survival probability is claimed.','- The prop observer implements floating-equity rules, real trading days, phase resets and censored survival with controlled tests. Named firm rules and fees are not verified; hypothetical rules must not be labeled firm qualification.','- Current source-hashed local research jobs persist canonical state, funnel identity sets, full account ledgers and emitted-signal identities atomically. Earlier screens lack that full source pin and remain provisional.','- Long-term independent periods, full walk-forward qualification and sufficiently granular execution evidence remain necessary before a demo shortlist can be approved. The 2026 October window has now been observed and cannot become an untouched holdout for subsequent tuning.','','## Strategy classifications','','| Strategy | Classification | Largest single-study closed sample |','|---|---|---:|']
for s in index['strategyInventory']:lines.append(f"| {s['strategy']} | {s['classification']} | {s['largestSingleStudyClosedSample']} |")
path=pathlib.Path('docs/research/mission2/ACTUAL_RESULTS.md');path.write_text('\n'.join(lines)+'\n');print(path)
